// inventory row: { roomType, night, total, booked }
// holds table: { holdId, roomType, night, createdAt }

function takeHold(db, holdId, roomType, night) {
  db.exec("UPDATE inventory SET booked = booked + 1 "
    + "WHERE roomType = ? AND night = ?", roomType, night);
  db.exec("INSERT INTO holds(holdId, roomType, night, createdAt) "
    + "VALUES (?, ?, ?, now())", holdId, roomType, night);
  return holdId;
}

function confirm(db, holdId) {
  // payment already captured by caller; mark the booking confirmed
  db.exec("INSERT INTO bookings(holdId) VALUES (?)", holdId);
  return "confirmed";
}

function releaseExpired(db) {
  const stale = db.query("SELECT * FROM holds WHERE createdAt < now() - INTERVAL 15 MINUTE");
  for (const h of stale) {
    db.exec("UPDATE inventory SET booked = booked - 1 "
      + "WHERE roomType = ? AND night = ?", h.roomType, h.night);
    db.exec("DELETE FROM holds WHERE holdId = ?", h.holdId);
  }
}
